 "decisions": [
  {
   "title": "Data migrates to the target database",
   "context": "The legacy reads and writes tables in three databases (db_pagos, db_admin, db_cuentas) and the target keeps its data in SQL Server, so the legacy's own engine is not the target's.",
   "decision": "data_strategy is migration: the four tables (pg_orden, ad_tarifa_empresa, ad_servicio, ct_cuenta) move to the target database under snake_case names without the legacy database qualifiers, keeping the legacy columns and precision. Each is accessed through a repository port.",
   "consequences": "A data migration and reconciliation of the four tables is needed before cut-over. The service no longer depends on the legacy databases for reads and writes of its own data."
  },
  {
   "title": "Account debit behind a port",
   "context": "The legacy calls db_cuentas..sp_debito, which owns the account movements and returns the movement sequence in @o_secuencial.",
   "decision": "The debit stays behind the DebitGateway port, which keeps the legacy_program and the argument and output traceability of sp_debito. The adapter is implemented against the migrated account data and must take part in the same transaction as the order update, and its non-zero status is raised as a failure.",
   "consequences": "The debit rules of sp_debito must be provided by the adapter in the target and verified against the golden master. The port isolates the use case from how that is done."
  },
  {
   "title": "One transaction from the first debit to the order update",
   "context": "The legacy opens the transaction (line 108) just before the debit and commits at line 161. It has three rollback points and no savepoints.",
   "decision": "PayOrder declares a unit of work with begin 108, commit 161 and three full rollbacks (119 -> DEBIT_FAILED, 136 -> COMMISSION_DEBIT_FAILED, 155 -> ORDER_UPDATE_FAILED). The validations before line 108 run without a transaction. Any rejection raises the business error, which undoes the transaction.",
   "consequences": "A debit is never kept when the commission debit or the order update fails. No UnitOfWork port is needed because there are no savepoints."
  },
  {
   "title": "Status of sp_debito becomes an exception",
   "context": "The legacy checks @w_return <> 0 or @@error <> 0 after each debit. Error-code plumbing is not translated.",
   "decision": "The DebitGateway adapter raises a failure on a non-zero status. The use case maps the first debit failure to DEBIT_FAILED and the commission failure to COMMISSION_DEBIT_FAILED. The movement sequence is the @o_secuencial output of the first debit only.",
   "consequences": "The commission debit has no returned movement, as in the legacy."
  },
  {
   "title": "Behaviour preserved on missing data",
   "context": "The legacy does not reject a missing account or service, because comparisons with NULL are not true and a NULL tariff becomes 0.",
   "decision": "If the account does not exist, the funds check does not reject and the debit is delegated to the gateway. If neither tariff exists, the tariff is 0. The canal input defaults to 'WEB' when absent, as in the legacy.",
   "consequences": "Same results as the legacy, and the behaviour is visible to reviewers."
  },
  {
   "title": "Decimal arithmetic",
   "context": "Amounts are money in the legacy (decimal(19,4)). The WEB commission is round(tarifa / 2, 2).",
   "decision": "Use BigDecimal with scale 4 and round the half-tariff to 2 decimals with HALF_UP. The overdraft margin of 100.00 for non-VIR accounts is a business constant.",
   "consequences": "Results match the legacy for the golden master cases."
  },
  {
   "title": "Infrastructure not translated",
   "context": "The ERROR label calls cobis..sp_cerror to log the error and returns the error code.",
   "decision": "sp_cerror is not translated. Business exceptions carry a stable code and message, and the error handler of the framework replaces it.",
   "consequences": "The rejection message is returned through the message output and the error code of the response."
  }
