using Bank.Payments.Domain.Port;
using Bank.Payments.Infrastructure;

namespace Bank.Payments.Adapters.Out.Sql;

/// <summary>
/// Adapter of DebitGateway (legacy db_cuentas..sp_debito) against the migrated account data.
/// It runs inside the transaction of the request, so a later rejection undoes the debit.
/// A debit that cannot be applied (account not found, or a null amount) is raised as an
/// exception, which stands for the non-zero status of sp_debito.
/// </summary>
public sealed class SqlDebitGateway(Db db) : DebitGateway
{
    public int DebitOrder(string? cuenta, string? tipoCuenta, decimal? valor, string? referencia)
    {
        Debit(cuenta, tipoCuenta, valor, referencia);
        // The target schema has no movement table, so the sequence is the fixed value 1.
        return 1;
    }

    public int DebitCommission(string? cuenta, string? tipoCuenta, decimal? valor, string? referencia)
    {
        Debit(cuenta, tipoCuenta, valor, referencia);
        // The commission debit has no returned movement, as in the legacy.
        return 0;
    }

    private void Debit(string? cuenta, string? tipoCuenta, decimal? valor, string? referencia)
    {
        if (valor is null)
        {
            throw new InvalidOperationException("sp_debito: amount is required");
        }

        const string sql =
            "UPDATE ct_cuenta SET cta_saldo = cta_saldo - @valor " +
            "WHERE cta_numero = @cuenta AND cta_tipo = @tipo";

        using var command = db.Command(sql);
        command.Parameters.AddWithValue("@valor", (object?)valor ?? DBNull.Value);
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        command.Parameters.AddWithValue("@tipo", (object?)tipoCuenta ?? DBNull.Value);

        var affected = command.ExecuteNonQuery();
        if (affected <= 0)
        {
            throw new InvalidOperationException(
                $"sp_debito: account {cuenta}/{tipoCuenta} not found (reference {referencia})");
        }
    }
}
